		/** 
		 * Tests creating a new Terminal.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Terminal");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Terminal" );

			try {            
				Terminal entity = TerminalService.getTerminalInstance().createTerminal( generateNewEntity() );
				thePrimaryKey = entity.getTerminalId();
				LOGGER.info( "-- Successfully created a Terminal with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Terminal. 
		 */
		public Terminal testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Terminal" );

			Terminal entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Terminal with primary key" );
			msg.append( thePrimaryKey );
			
			TerminalFetchOneSummary fetchOneSummary = new TerminalFetchOneSummary( thePrimaryKey );

			try {
				entity = TerminalService.getTerminalInstance().getTerminal( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Terminal " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Terminal.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Terminal." );

			StringBuilder msg = new StringBuilder( "Failed to update a Terminal : " );        
			Terminal entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Terminal." );

				// for use later on...
				thePrimaryKey = entity.getTerminalId();

				TerminalService proxy = TerminalService.getTerminalInstance();            
				proxy.updateTerminal( entity );   

				LOGGER.info( "-- Successfully saved Terminal - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Terminal.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Terminal." );

			try{
			    Terminal entity = testRead(); 
				TerminalService.getTerminalInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Terminal with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Terminal with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Terminals.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Terminals:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Terminal : " );        
			List<Terminal> collection  = null;

			try {
				// call the static get method on the TerminalService
				collection = TerminalService.getTerminalInstance().getAllTerminal();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Terminal entity = null;            
					Iterator<Terminal> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getTerminalId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

